import{_ as o,o as l,c as i,ag as a}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"02 房产实战手册（源自天涯13帖的知识萃取）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/02_房产实战手册.md","filePath":"topics/tianya/handbook/02_房产实战手册.md"}'),r={name:"topics/tianya/handbook/02_房产实战手册.md"};function u(q,t,n,s,e,h){return l(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="_02-房产实战手册-源自天涯13帖的知识萃取" tabindex="-1">02 房产实战手册（源自天涯13帖的知识萃取） <a class="header-anchor" href="#_02-房产实战手册-源自天涯13帖的知识萃取" aria-label="Permalink to &quot;02 房产实战手册（源自天涯13帖的知识萃取）&quot;">​</a></h1><blockquote><p>知识来源：38/40/41/42/44/46/48/50/69/80/88/100/197号帖。文中【n】为帖号。所有判断标准与数字均出自原帖原文；&quot;失效条件&quot;指2021年后市场结构变化对该方法的侵蚀。</p></blockquote><h2 id="一、选城与选房框架" tabindex="-1">一、选城与选房框架 <a class="header-anchor" href="#一、选城与选房框架" aria-label="Permalink to &quot;一、选城与选房框架&quot;">​</a></h2><h3 id="_1-1-三因子选城法【46】" tabindex="-1">1.1 三因子选城法【46】 <a class="header-anchor" href="#_1-1-三因子选城法【46】" aria-label="Permalink to &quot;1.1 三因子选城法【46】&quot;">​</a></h3><p><strong>命题</strong>：短期房价由首付比例、利率、房产政策决定；长期房价由人口决定。人口净流出的城市，绝对不适合投资房产。</p><p><strong>操作步骤</strong>：</p><ol><li>查城市常住人口连续5年机械增长（流入为正）。人口净流出城市直接出局，无论价格多便宜。</li><li>查政策：城市是否限购限贷。限购=需求被人为压制，是机会不是风险（见5.1）；不限购的都市圈周边小城市反而要警惕——那是限购挤出的资金去填的坑。</li><li>查流动性：打开二手房平台，看该城市/板块二手房源的成交周期与成交量。二手房能顺利卖掉、且与新房价差不悬殊，市场结构才健康；卖不掉或一二手倒挂严重，说明该城市供应大量过剩。</li></ol><p><strong>判断标准（海男的负面清单）</strong>：</p><ul><li>坑一：2011年限购把资金逼去的三四线城市——房子不涨反跌，且有价无市，&quot;认错的机会都不给&quot;。</li><li>坑二：大都市圈附近不限购的小城市（如环京、环沪、环深）——绝大部分房子将面对&quot;租不掉、卖不掉、住不了&quot;。</li><li>城市定性问题问两句话：公共资源好不好？产业好不好？两样都差的（如绍兴这类有钱人流入少、本地无高薪岗位的城市）不适合投资。</li></ul><p><strong>适用条件</strong>：2016-2021年的城市化中期，人口继续向大都市圈集中。<strong>失效条件</strong>：人口负增长时代（2022年后），&quot;人口流入&quot;的均值判断须细化为&quot;高学历年轻人流入&quot;；都市圈小城市在棚改与脉冲行情中的反弹不代表长期价值。</p><h3 id="_1-2-财政依赖度→政策打折推演【100】" tabindex="-1">1.2 财政依赖度→政策打折推演【100】 <a class="header-anchor" href="#_1-2-财政依赖度→政策打折推演【100】" aria-label="Permalink to &quot;1.2 财政依赖度→政策打折推演【100】&quot;">​</a></h3><p><strong>命题</strong>：地方政府税收接近八成由房地产产业链提供——地税口径中约四成半来自房地产行业，一成半来自建筑相关行业，两成半来自与房地产高度关联的金融业；再算上土地出让金，地方政府收入的八成以上拴在房地产上。</p><p><strong>操作步骤</strong>：</p><ol><li>遇到任何调控政策，先问：这个政策伤不伤地方税基和卖地收入？</li><li>伤得越深，执行时被打的折扣越大（限价改备案价、限签窗口操作、人才购房变相放开都是打折形式）。</li><li>由此推演：房价大跌→缩量→税收瘫痪→地方财政入不敷出→开发商资金链断裂→银行抵押品缩水，这条链是国家必须阻止的，所以&quot;没有可能大幅下滑&quot;是该框架下的默认状态，除非链条被更高意志（金融去杠杆、房住不炒）强行改写。</li></ol><p><strong>判断标准</strong>：政策文本是&quot;抑制过快上涨&quot;=默认还会涨，只是别太快；&quot;坚决遏制房价上涨&quot;（2018.7.31政治局会议原文）=措辞升级，默认状态被改写，是框架失效的前兆信号。看政策要看动词强度变化，不要看标题。</p><p><strong>适用与失效</strong>：适用2003-2021年土地财政周期。失效于2021年后：当中央把&quot;去杠杆&quot;置于地方税基之上、房产税立法启动，财政依赖度不再自动转化为政策托底。</p><h3 id="_1-3-房价构成公式与洼地判断【46】" tabindex="-1">1.3 房价构成公式与洼地判断【46】 <a class="header-anchor" href="#_1-3-房价构成公式与洼地判断【46】" aria-label="Permalink to &quot;1.3 房价构成公式与洼地判断【46】&quot;">​</a></h3><p><strong>公式</strong>：房价=地段（30-40%）+小区及房子品质（20-30%）+小区附近环境（10-15%）+教育资源（5-20%）+二级商务资源（10%）+商业资源（10%）。地段以&quot;到达主流CBD的便捷程度和时间&quot;衡量，不是环线。</p><p><strong>操作步骤</strong>：把目标房源按上表逐项打分，全部组成已成熟的市区盘，价格已包含各项价值，涨跌随大势、没有额外惊喜；近郊与市区边缘盘才有&quot;洼地&quot;——修条地铁、建个学校，单变量就能拉动整段价格。</p><p><strong>关键数字</strong>：CBD企业高管住企业附近，中高层买在5站地铁通达处，普通员工买在15站以内——按自己资金实力沿这条&quot;通勤带&quot;选房，一般能保值增值；高新区旁、有学校配套的近郊盘优先。</p><p><strong>失效条件</strong>：学区政策频繁调整（多校划片、教师轮岗），教育资源权重（5-20%）是六项中风险最高的一项，押注时须打折。</p><h3 id="_1-4-城市分层的世界坐标【40】" tabindex="-1">1.4 城市分层的世界坐标【40】 <a class="header-anchor" href="#_1-4-城市分层的世界坐标【40】" aria-label="Permalink to &quot;1.4 城市分层的世界坐标【40】&quot;">​</a></h3><ul><li>中国11个最有投资价值的城市（2015年口径）：北京、上海、广州、深圳、厦门、天津、南京、杭州、重庆、武汉、成都。</li><li>胡焕庸线东南32%的国土住着94%的人口，&quot;中国是放大了的日本&quot;；日本28%人口住在东京圈，房价狂潮绝大部分发生在东京，大阪福冈只有东京三分之一，乡镇房产一百万日元白送——城市化的终局是都市圈化。</li><li>美国高房价城市只有纽约、洛杉矶、旧金山三个，其余地方房产完全不稀缺（小镇25万美元=建筑8万+地价8万+许可8万）。</li><li>城市化两阶段：第一阶段农村→城市，各城普涨；第二阶段小城→大城，只有人口流入城市涨。2000年后中国处于第二阶段。</li></ul><h2 id="二、二手房流动性-体温计-【88】" tabindex="-1">二、二手房流动性&quot;体温计&quot;【88】 <a class="header-anchor" href="#二、二手房流动性-体温计-【88】" aria-label="Permalink to &quot;二、二手房流动性&quot;体温计&quot;【88】&quot;">​</a></h2><p><strong>命题</strong>：换手率与二手房成交是最诚实的市场指标。媒体可以唱多唱空，法拍、成交周期、真实降价幅度不会撒谎。</p><p><strong>操作步骤</strong>（dindindanglaile的日常功课）：</p><ol><li>盯同小区同户型的链家/中原/Q房多平台挂价与成交价，记录价差。2018年她抓到实例：罗湖畔山花园挂4.2万/平，加税费佣金到手成本4.5万，实际成交3.7万——账面&quot;持平&quot;实为每平亏7千。</li><li>盯法拍房：法拍价≈市场底价信号。龙岗某盘一拍297万流拍、二拍237万流拍、三拍预期170万——法拍连续流拍=底部远未到。</li><li>盯笋盘出现频率：正常市场笋盘稀缺；某天&quot;一夜之间几套业主同时松动降价&quot;，说明资金面突变（她那次的直接原因是2017年5月底加息），是行情转弱的实时信号。</li><li>盯中介动向：中介门店关闭、中介转行去三四线或回家，是行业先于价格收缩的信号（2017年5月北京新政后成交量跌七八成，中介迁往承德、唐山、海南）。</li></ol><p><strong>该卖的信号清单</strong>：</p><ul><li>同小区挂牌量持续增加、成交周期拉长到三个月以上；</li><li>法拍房开始出现且一拍即流拍；</li><li>业主群体性降价（&quot;一夜之间都缺钱了&quot;）；</li><li>政策面出现&quot;坚决遏制房价上涨&quot;级别的措辞升级【69】；</li><li>板块主要购房人群（80后公务员、加杠杆的年轻人）开始断供式抛售——原帖实例：80后公务员业主两年前&quot;存款15万+信用卡套15万&quot;凑30万首付买115万的房，2017年5月主动降价10万一周出手。</li></ul><p><strong>换房&quot;先卖后买&quot;链条为何脆弱</strong>：一次换房至少串起三方——你卖旧房（买家可能贷款被拒、被新政取消资格）、你买新房（卖家可能坐地涨价、被限购限贷冻结）、上游还有卖家的卖家。2017年3月北京商办新政一例：90后情侣先签买房合同、当晚赶回昌平签卖房合同庆祝，新政3天后商办签约跌99.9%，链条上五家人全部被冻住，违约金加中介费损失17万【69】【88】。</p><p><strong>防御操作</strong>：</p><ol><li>卖房合同里加&quot;政策变动免责解约条款&quot;；</li><li>买家定金尽量收高（定金越高买家毁约成本越大）；</li><li>过户前不签任何买入合同——原帖楼主的操作是&quot;卖了再看，钱在手上，谈判底气也足&quot;；</li><li>卖房时间点避开政策敏感期（两会后、政治局会议后是新政高发窗口）。</li></ol><p><strong>失效条件</strong>：流动性指标在上涨期会失灵——2019-2021年反弹期持币者踏空；体温计只能确认趋势，不能预测脉冲。</p><h2 id="三、杠杆的纪律" tabindex="-1">三、杠杆的纪律 <a class="header-anchor" href="#三、杠杆的纪律" aria-label="Permalink to &quot;三、杠杆的纪律&quot;">​</a></h2><h3 id="_3-1-租金覆盖月供判断法【50】" tabindex="-1">3.1 租金覆盖月供判断法【50】 <a class="header-anchor" href="#_3-1-租金覆盖月供判断法【50】" aria-label="Permalink to &quot;3.1 租金覆盖月供判断法【50】&quot;">​</a></h3><p><strong>命题</strong>：穷人怕借钱、富人喜融资；只要租金能覆盖月供，&quot;你借的越多，就赚的越多&quot;。</p><p><strong>操作步骤</strong>：</p><ol><li>算目标房源月租金与月供之比。月租金≥月供，等于用租客替你还贷，你的自有资金在免费放大；</li><li>月租金&lt;月供时，缺口必须小于家庭月结余，且预留6-12个月月供的现金池；</li><li>区分两种负债：富人借钱买生息资产（融资），穷人借钱消费治病（背债）——&quot;富人越借越富，穷人越借越穷&quot;；</li><li>白手起家者优先用银行贷款（无人情债、利率最低、期限最长），民间借款给足利息。</li></ol><p><strong>关键数字</strong>：晋朝人1999年首套房单价2560元/平，月供1500元≈当时月薪1500元——他事后承认这是&quot;月供枷锁&quot;的起点；反例是他劝长者贷款买写字楼被拒：&quot;只要租金还贷后有剩余，说明你的回报超过贷款利率，相当于借银行的钱去赚钱。&quot;</p><p><strong>失效条件</strong>：该法则成立的前提是房价长期上涨+租金稳定。2021年后租金融胀脱钩、部分城市租金下行，&quot;租金覆盖月供&quot;在高位接盘的城市可能十年不达成，杠杆从引擎变成枷锁——法则是中性的，成败取决于买入价格与城市选择（即第一章）。</p><h3 id="_3-2-月供枷锁的真实成本账本【80】" tabindex="-1">3.2 月供枷锁的真实成本账本【80】 <a class="header-anchor" href="#_3-2-月供枷锁的真实成本账本【80】" aria-label="Permalink to &quot;3.2 月供枷锁的真实成本账本【80】&quot;">​</a></h3><p>房奴十年帖的十年流水，是把&quot;月供压力&quot;量化成生活成本的原始数据：</p><ul><li>2010年购深圳偏远期房总价50万，月入7000，等额本金月供2784元，自定&quot;五年还清&quot;目标，另每年交12000元保险；</li><li>为还贷的实际生活：搬进10元/晚的十元店，日餐3元（两根香蕉0.6元+白香瓜2.7元），步行通勤月省100元，捡到5毛钱记入账本；麦当劳钟点工时薪5元还要自付押金、健康证85元；</li><li>2018年仍在记账：年支出13812元（房租6600+伙食4200+网费1092+交通1152+电432+水168+话费168），&quot;一年房贷13812乘以n倍&quot;；</li><li>因租客身份被房东九次驱赶、扣押金——&quot;有房&quot;首先是尊严与稳定问题，其次才是资产问题。</li></ul><p><strong>判断标准</strong>：月供不超过家庭月收入40%【80的2784/7000=40%就是她的极限】；首付掏空六个钱包后仍须留出保险与应急金。<strong>融资纪律</strong>：不卖旧房、靠信用贷/抵押融资买二套的方案，先算总成本——税费三倍+融资成本年化约8%，房价年涨幅低于15%就是给自己挖坑【88】，&quot;有多大能力办多大事&quot;。<strong>教训</strong>：买在偏远片区（50万的房&quot;地方相当偏僻&quot;）意味着升值的贝塔远弱于核心区，枷锁戴了十年、涨幅跑输大势——错的不该是买房，是买错房。</p><h2 id="四、多空判断框架-从信仰到可检验条件" tabindex="-1">四、多空判断框架：从信仰到可检验条件 <a class="header-anchor" href="#四、多空判断框架-从信仰到可检验条件" aria-label="Permalink to &quot;四、多空判断框架：从信仰到可检验条件&quot;">​</a></h2><h3 id="_4-1-为什么-带条件的判断-活到2026" tabindex="-1">4.1 为什么&quot;带条件的判断&quot;活到2026 <a class="header-anchor" href="#_4-1-为什么-带条件的判断-活到2026" aria-label="Permalink to &quot;4.1 为什么&quot;带条件的判断&quot;活到2026&quot;">​</a></h3><p>复盘13帖的预测存活率：</p><ul><li>死亡的是无条件信仰：&quot;房价10年内都不会跌&quot;【38】——2010-2020大体对，2021-2026错，&quot;10年&quot;边界一破全盘皆输；&quot;屡创新高直到让你绝望&quot;【40】——停在2021年；&quot;买房像春天播种，不用看天气&quot;【197】——2020年那次播对了，作为永久法则则死于人口拐点。</li><li>存活的是带条件的判断：&quot;泡沫不破，什么时候会大跌？经济危机&quot;【46】——2021-2026年恰是&quot;经济下行+温和阴跌&quot;组合，兑现；&quot;没有任何一种大类资产可以长期跑赢货币增长，房地产也没有&quot;【100】——把房子从&quot;信仰&quot;降格为&quot;货币的影子资产&quot;，2026年完全成立；&quot;中美蜜月结束，未来是敌对关系&quot;【44】——2018年写下，此后五年逐条兑现。</li></ul><p><strong>原理</strong>：信仰是&quot;无条件、无时间边界、无观察指标&quot;的命题，无法被反驳也无法被修正；带条件的判断内含触发器（经济危机、货币增速、政策措辞），触发器变了结论就变。楼市长周期中多空都会轮到自己的季节，唯一穿越牛熊的是&quot;条件-验证-修正&quot;循环。</p><h3 id="_4-2-改写示范-把信仰改写成可检验命题" tabindex="-1">4.2 改写示范：把信仰改写成可检验命题 <a class="header-anchor" href="#_4-2-改写示范-把信仰改写成可检验命题" aria-label="Permalink to &quot;4.2 改写示范：把信仰改写成可检验命题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信仰（原帖原话）</th><th>改写后的可检验命题</th></tr></thead><tbody><tr><td>&quot;10年内房价都不会跌&quot;【38】</td><td>&quot;在居民杠杆率未见顶、土地财政未转向、货币政策宽松的条件下，房价不跌；三者任一逆转即重估&quot;——观察指标：居民新增房贷占新增贷款比例【69：2016年达45%即预警】、政治局对房价的措辞动词【100】、M2增速【100】</td></tr><tr><td>&quot;一线永远涨，涨到你绝望&quot;【40】</td><td>&quot;人口净流入+高端岗位集中+供应受限的一线核心区，跑赢货币增速；当租金与房价脱钩、换手率降至2%以下持续两年，看多条件失效&quot;【44/197：北京换手率2%是常量样本】</td></tr><tr><td>&quot;房价会腰斩&quot;【48】</td><td>&quot;名义房价未必跌，但若房价涨幅持续低于必需品与黄金涨幅，购买力口径已腰斩——用牛肉面和金价做折算尺&quot;（2016年提出，2021-2026部分应验）</td></tr><tr><td>&quot;明年房价大跌，一年白干&quot;【42】</td><td>&quot;去杠杆=货币收缩=资产价格下行；观察首套房贷利率连升月数与新增房贷额度压缩幅度&quot;【69：2017年利率四连升+2017年新增房贷4万亿、较2016年砍半，2018年即应出货】</td></tr><tr><td>&quot;刚需什么时候上车都对&quot;</td><td>&quot;自住看承受力：月供≤收入40%、留足应急金、买通勤带内二手可成交的盘——三条件不满足时，刚需上车也是错的&quot;【80/88】</td></tr></tbody></table><p><strong>通用改写规则</strong>：①写出触发器（什么信号出现结论作废）；②写出观察指标与频率；③写出时间边界；④预设证伪后的动作（卖出/减仓/持币）。</p><h2 id="五、买房时点论" tabindex="-1">五、买房时点论 <a class="header-anchor" href="#五、买房时点论" aria-label="Permalink to &quot;五、买房时点论&quot;">​</a></h2><h3 id="_5-1-调控期窗口论【46】" tabindex="-1">5.1 调控期窗口论【46】 <a class="header-anchor" href="#_5-1-调控期窗口论【46】" aria-label="Permalink to &quot;5.1 调控期窗口论【46】&quot;">​</a></h3><p><strong>机制</strong>：房价涨→地方卖地→开发商拿地→中央调控（限购限贷）→市场冰冻、开发商放缓开工→供应没上去但需求没消失→调控松绑→积压需求火山喷发→供不应求→暴涨→再调控，周而复始，&quot;坑爹无极限&quot;。</p><p><strong>操作含义</strong>：限购限贷是房产投资的福音【46，原话重复三遍】——它人为制造供不应求，给多军制造了可预见的下一波。买入窗口=调控最深、成交量冰冻、媒体集体唱衰之时；卖出窗口=调控松绑后量价齐升、赚钱效应引诱投机资金进场之时。</p><p><strong>关键数字</strong>：2011年大中城市限购→大城市2011-2014供应萎缩→2014.9/2015.3新政松绑→积压需求爆发，2015年深圳二手房涨23%、广州12%、上海7%、北京5%（当年9月至2015年5月涨幅【40】），随后2016年全国翻倍行情。</p><h3 id="_5-2-救市信号识别清单【40】" tabindex="-1">5.2 救市信号识别清单【40】 <a class="header-anchor" href="#_5-2-救市信号识别清单【40】" aria-label="Permalink to &quot;5.2 救市信号识别清单【40】&quot;">​</a></h3><p>2014-2015年&quot;最后的救市&quot;原文给出的观察点：</p><ol><li>政策端：930新政（2014.9认贷不认房）、330新政（2015.3二套首付降至4成）连续出台——救市的目的不是救房地产，是救地方财政与债务，所以力度会不断加码直到市场回暖；</li><li>成交端：一线城市二手成交量创阶段新高（北京2015年4月二手成交1.71万套，25个月新高）；</li><li>价格端：一线房价率先回升（2015年5月深圳涨23%居首），二三线滞后——&quot;救市后还没涨的城市，就再也不会涨了&quot;是该框架的分层结论；</li><li>行为端：日光盘重现、业主坐地涨价、买家毁约跳价（600万成交前夜加10万【69】）——赚钱效应确立。</li></ol><p><strong>操作</strong>：救市信号出现时，卖三四线换一线强二线（11城清单见1.4）；三四线此时不出，&quot;将来面对的是有价无市，砸在手里&quot;。</p><p><strong>失效条件</strong>：2015-2017棚改货币化让三四线又涨一轮，证明&quot;救市后不涨的城市永远不涨&quot;过于绝对；2021年后再无全国性救市，信号清单降级为&quot;城市自发的松绑&quot;，效力递减。</p><h3 id="_5-3-资金面拐点信号【69】【88】" tabindex="-1">5.3 资金面拐点信号【69】【88】 <a class="header-anchor" href="#_5-3-资金面拐点信号【69】【88】" aria-label="Permalink to &quot;5.3 资金面拐点信号【69】【88】&quot;">​</a></h3><ul><li>首套房贷利率连续上升月数（2017年前4个月连升，4月均值4.52%）；</li><li>居民新增房贷额度压缩幅度（2017年计划4万亿，较2016年降50%）；</li><li>银行间资金价格（2017年5月10年期国债收益率破3.5%，隔夜回购创25个月新高）；</li><li>加息/缩表动作与&quot;商住限购&quot;这类定向冻结（2017年3.26北京商办新政，3天签约跌99.9%）。 上述任意两项同时出现，市场由暖转冷，买方应转入观望，卖方抓住窗口出货。</li></ul><h2 id="六、中介与卖方话术应对【88】" tabindex="-1">六、中介与卖方话术应对【88】 <a class="header-anchor" href="#六、中介与卖方话术应对【88】" aria-label="Permalink to &quot;六、中介与卖方话术应对【88】&quot;">​</a></h2><p><strong>中介的立场由佣金决定</strong>：3个点是公司铁规，带看小伙没有打折权限；一套500万的房个人佣金可达10万【88】，所以中介天然帮卖家抬价、帮双方快成交，不帮任何一方省钱。</p><p><strong>实战话术拆解（原帖案例）</strong>：</p><ol><li>&quot;我们有谈判专家，至少从减18万开谈&quot;——买家自曝底价（-15，最多加3万）后，&quot;谈判专家&quot;开场就逼买家出价，卖家全程&quot;笑而不语&quot;，最终砍到-12成交，比买家心理底价还高，佣金还要3个点。</li><li>分会议室谈判：僵持时把一方请进另一间&quot;做思想工作&quot;，实为配合另一间施压。</li><li>&quot;好房急卖，已有人定&quot;戏码：先朋友圈发急卖、两天后截屏宣布已卖，一个月后该房仍在网上挂着且降价了——成交量造假的标准剧本。</li><li>洗盘：中介隔三差五电话确认&quot;还卖吗&quot;，同时收集你的底价与急迫度。</li><li>税费结构是硬约束：满二与否差增值税5.6%、个税1个点、佣金3个点【88】——报价低但不满二的房，实际成本可能反超。</li></ol><p><strong>应对清单</strong>：</p><ul><li>谈判前写下底价并封存，谈判桌上只说&quot;不合适&quot;，绝不透出口头底价；</li><li>要求与业主直接对坐谈判，拒绝&quot;背对背&quot;传话；</li><li>佣金谈判找有权限的店长/总监（原帖3个点→1.8个点即总监权限）；</li><li>用多平台成交价（非挂价）核价，链家成交+中原+Q房交叉验证；</li><li>噪音用分贝计实测（原帖白天42-47分贝的量化记录），楼层朝向缺陷现场验证，不听口头描述。</li></ul><h2 id="七、空军的代价-行为金融教训清单【41】" tabindex="-1">七、空军的代价：行为金融教训清单【41】 <a class="header-anchor" href="#七、空军的代价-行为金融教训清单【41】" aria-label="Permalink to &quot;七、空军的代价：行为金融教训清单【41】&quot;">​</a></h2><p>爱死小肥羊帖是&quot;傻空&quot;的完整病理标本，损失远超账面：</p><ol><li><strong>确认偏误</strong>：只接受对自己有利的信息——&quot;天天上网看牛刀，笃定2010年1、2月必跌&quot;，房价从3000+涨到7500，信念从未更新；</li><li><strong>锚定死价</strong>：&quot;不到3500绝不出手&quot;——把心理价位当市场公允价，四年间每次临门一脚都撤退（看了ky、东区、南区反复横跳），一年后同小区成交价比其底价高100万量级；</li><li><strong>机会成本不可见</strong>：损失的3500元/平差价人人会算，没人算&quot;三年房租3万+装修晾晒时间+婚期推迟+关系破裂&quot;——她的总结：&quot;房价涨跌不过区区几万，这时间这青春年华才是最宝贵的&quot;；</li><li><strong>沉没成本谬误的反向版</strong>：等得越久越不肯认错，&quot;万一到时候又涨了，多花几万算我的&quot;——用承诺升级掩盖错误；</li><li><strong>权威替代思考</strong>：把判断外包给网红空军（牛刀），空军自己在北京上海深圳都有房【40】——唱空是生意，买房是生活；</li><li><strong>关系内耗</strong>：预测分歧升级为价值观战争，2011年分手，男方取走她卡里1万多元——错误的代价由两人分摊，且以最难挽回的形式（时间与感情）支付；</li><li><strong>幸存者偏差的镜像</strong>：空军赢一次（2021年后的下跌）会获得迟到十年的正名，但在2010-2021的漫长兑现期里，空军损失的是全部上车机会——与多军&quot;买错房&quot;对称，&quot;不买房&quot;同样是一种满仓决策。</li></ol><p><strong>清单化行动规则</strong>：给买房决策设观察期（原帖读者的建议：&quot;设定观察期，到期没达到设想就结束观察期行动&quot;）；观察期内只看数据不看大V；观察期结束时按当期市价执行，不追讨心理价位。</p><h2 id="八、2019年持币-vs-买房复盘-事后看是卖点-买点的信号" tabindex="-1">八、2019年持币 vs 买房复盘：事后看是卖点/买点的信号 <a class="header-anchor" href="#八、2019年持币-vs-买房复盘-事后看是卖点-买点的信号" aria-label="Permalink to &quot;八、2019年持币 vs 买房复盘：事后看是卖点/买点的信号&quot;">​</a></h2><p>2019年初（88帖末段）市场给出的完整信号集，事后回看多数是卖点：</p><ol><li><strong>法拍连续流拍</strong>：龙岗盘一拍297万→二拍237万流拍→预期三拍170万——折扣链未走完，市场底部未到；</li><li><strong>板块跌回起点</strong>：龙中多盘&quot;已跌回2015年下半年&quot;，斩仓保命的房东是先知，等反弹的是泪两行；</li><li><strong>新房抢跑</strong>：同一新盘从7月单价2.8万降到8月2.1万精装——开发商现金流优先于价格纪律；</li><li><strong>政策最后泄洪</strong>：2019年初部分城市放开限购，楼主解读&quot;大堤千疮百孔，只能放开闸门狠狠减下容，否则决堤&quot;——放松限购不等于看多信号，是找接盘侠；</li><li><strong>首付分期促销</strong>：&quot;首付7天内交40%、3个月30%、半年30%&quot;——连首付都要分期，接盘侠稀缺到了极点；</li><li><strong>租金与空置异动</strong>：新建小区200户只入住十几户、临街商铺成片招租、商场品牌店撤场改特卖场——消费降级先于房价下跌出现；</li><li><strong>微观收入端</strong>：年终奖欠发、同事返乡、家族&quot;因房返贫&quot;案例（50万贷款盖房+100万负债）——居民现金流恶化先于资产价格；</li><li><strong>反向案例（买点信号）</strong>：同期66端午88记录&quot;基本算稳住了，等待反弹时机&quot;【100】，2019年3月A股启动——资产从房转股的替代周期开启，&quot;没有任何大类资产跑赢货币增长&quot;意味着资金在股/房间轮动，持币者的机会成本真实存在。</li></ol><p><strong>复盘结论</strong>：2019年卖点信号（1-7）齐备但房价此后仍脉冲至2021年——流动性体温计只能确认趋势、不能掐准顶点；正确的动作是分批减仓而非一次清仓。持币的代价（2019-2021踏空）与买房的代价（2021-2026套牢）对称，最优解是88帖楼主无意中实践的结构：核心区自住一套+充足现金+持续盯盘的耐心，不赌单边。</p><h2 id="附-全书速查" tabindex="-1">附：全书速查 <a class="header-anchor" href="#附-全书速查" aria-label="Permalink to &quot;附：全书速查&quot;">​</a></h2><ul><li>选城：人口流入→政策→二手流动性，三关全过才出手【46】</li><li>选房：通勤带（CBD 5-15站）+洼地六因子打分【46】</li><li>杠杆：租金≥月供，月供≤收入40%，留6-12个月应急金【50/80】</li><li>时点：调控最深时买，松绑放量后卖【46/40】</li><li>出货信号：法拍流拍+板块跌回起点+新盘抢跑+限购&quot;泄洪&quot;【88/69】</li><li>谈判：封存底价、直谈业主、总监砍佣金、多平台核价【88】</li><li>纪律：一切结论写明触发器、观察指标、时间边界，触发即执行【42/44/46】</li></ul>',80)])])}const p=o(r,[["render",u]]);export{d as __pageData,p as default};
